// ═══ IllegalArgumentException — BAD INPUT ═══
public void withdraw(String accountId, BigDecimal amount) {
    // Validate ARGUMENTS:
    if (accountId == null || accountId.isBlank())
        throw new IllegalArgumentException("accountId must not be blank");
    if (amount == null || amount.signum() <= 0)
        throw new IllegalArgumentException("amount must be positive: " + amount);
    if (amount.scale() > 2)
        throw new IllegalArgumentException("amount max 2 decimal places: " + amount);
    // Caller's fault — they gave bad input. Fix: pass valid arguments.
}

// ═══ IllegalStateException — WRONG STATE ═══
public class TradingSession {
    private boolean open = false;

    public void open() { this.open = true; }
    public void close() { this.open = false; }

    public void executeTrade(Trade trade) {
        if (!open)
            throw new IllegalStateException("Trading session is CLOSED — call open() first");
        // Arguments are fine! But the session is in wrong state.
        // Caller's timing is wrong, not their input.
        process(trade);
    }
}

// ═══ ANOTHER ISE — iterator exhausted ═══
public class BatchIterator {
    private boolean consumed = false;

    public List<Trade> next() {
        if (consumed)
            throw new IllegalStateException("Iterator already consumed — create a new one");
        consumed = true;
        return fetchBatch();
    }
}

// ═══ Objects.requireNonNull — JDK standard for null checks ═══
public TradeResult process(Trade trade, Account account) {
    Objects.requireNonNull(trade, "trade must not be null");
    Objects.requireNonNull(account, "account must not be null");
    // Throws NullPointerException (NOT IAE!) — this is by design.
    // Joshua Bloch (Effective Java): NPE for null args is acceptable.
    return settle(trade, account);
}

// ═══ Guava Preconditions — explicit IAE/ISE ═══
import static com.google.common.base.Preconditions.*;

public void transfer(String from, String to, BigDecimal amount) {
    checkArgument(from != null && !from.isBlank(), "from required");     // → IAE
    checkArgument(amount.signum() > 0, "amount must be positive: %s", amount); // → IAE
    checkState(isConnected(), "Service not connected — call connect() first"); // → ISE
}

// ═══ DECISION GUIDE ═══
// Q: "Would this method work if the caller passed DIFFERENT arguments?"
//    YES → IllegalStateException (state is wrong, not input)
//    NO  → IllegalArgumentException (input is wrong)
//
// Q: "Is the problem with WHAT was passed or WHEN it was called?"
//    WHAT → IAE    WHEN → ISE
